-- perform/01-perf-data.sql — a ledger big enough to be slow: 30,000 postings.
-- Generated by arithmetic, never random(): every replay builds the same rows.
CREATE SCHEMA perf;
CREATE TABLE perf.postings AS
SELECT i                                      AS posting_id,
       1 + i % 300                            AS account_id,  -- 300 accounts
       date '2026-01-01' + i / 300            AS booked_on,   -- 100 days
       (((i * 37) % 20000 - 10000) / 100.0)::numeric(14,2) AS amount
FROM generate_series(0, 29999) AS i;
ALTER TABLE perf.postings ADD PRIMARY KEY (posting_id);
VACUUM ANALYZE perf.postings;   -- fresh statistics: 30,000 rows, all read
